package dao;import model.*;import java.sql.*;import java.util.*;
/** Đóng gói toàn bộ rạp -> phòng -> ghế/suất -> phim. Không tạo tham chiếu ngược gây vòng lặp. */
public class CinemaDAO5 extends DAO5 {public CinemaDAO5(Connection c){super(c);}public Cinema5[] getCinemas()throws Exception{List<Cinema5> all=query(Cinema5.class,"SELECT * FROM tblCinema5");for(Cinema5 c:all){List<ScreeningRoom5> rooms=query(ScreeningRoom5.class,"SELECT * FROM tblScreeningRoom5 WHERE tblCinema5id=?",c.getId());for(ScreeningRoom5 r:rooms){r.setListGhe(query(Seat5.class,"SELECT * FROM tblSeat5 WHERE tblScreeningRoom5id=? ORDER BY MaGhe",r.getId()).toArray(new Seat5[0]));List<Screening5> ss=query(Screening5.class,"SELECT * FROM tblScreening5 WHERE tblScreeningRoom5id=?",r.getId());for(int i=0;i<ss.size();i++)ss.set(i,new ScreeningDAO5(con).get(ss.get(i).getId()));r.setListSuatChieu(ss.toArray(new Screening5[0]));}c.setListPhongChieu(rooms.toArray(new ScreeningRoom5[0]));}return all.toArray(new Cinema5[0]);}}
